SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'kulturen_tab7', 'Bewässerte Kulturen / Flächen (Tab. 7 → strengste Güteklasse)', 'json', NULL, false, '§5.2, Tab. 7; Tab. 4 Anm. (*)', 'Plan 3: Zeilen je bewässerter Kultur-/Flächenart mit der gewählten Tab.-7-Zeile (TAB7_CLASS: Methode, Karenzzeit, Emitterabstand, laktierendes Vieh); min_rows(rank) → gueteklasse_code (M12001-08-D1); die 12 Ja/Nein-Fragen bleiben (Zuordnung zu Tab.-7-Zeilen m1200_1-J-1); Ableitung des manuellen gueteklasse_zugeordnet STAGED (m1200_1-D-2).', 'imported_unverified', '(*) Wenn eine bewässerte Kulturpflanzenart in mehrere der oben genannten Kategorien fällt, gelten die Anforderungen der strengsten Kategorie. — In Deutschland spezifiziert DIN 19650:1999 „Bewässerung - Hygienische Belange von Bewässerungswasser" Anforderungen für eine Bewässerung in Landwirtschaft, Gartenbau, Landschaftsbau sowie von Park- und Sportanlagen. DIN 19650:1999 unterscheidet vier Eignungsklassen, die die Anwendungsbereiche für Bewässerungswasser mit unterschiedlichen Qualitätsanforderungen definieren. Für eine einheitliche Regelung der Wasserwiederverwendung in Deutschland war es erforderlich, die Wassergüteklassen der EU-WasserWVVO (Tabelle 4) und die Eignungsklassen gemäß DIN 19650:1999 bezüglich der Anwendungsbereiche und Anforderungen zusammenzuführen. Weiterhin sind Spezifikationen der EU-Leitlinien zur Ausgestaltung der Wasserwiederverwendung (EU 2022/C 298/01) sowie ISO 16075-2:2020 „Leitlinien für die Nutzung behandelten Abwassers für Bewässerungsprojekte" zu beachten. Die Zusammenführung ist in Tabelle 7 erfolgt, in der die Güteklassen von aufbereitetem Wasser den Bewässerungsmethoden sowie den zulässigen landwirtschaftlichen Verwendungszwecken zugeordnet werden.', 'register', '{"title":"Bewässerte Kulturen / Flächen nach Tab. 7","subtitle":"je Kultur- bzw. Flächenart die gedruckte Tab.-7-Zeile (Güteklasse) wählen — die strengste Klasse gilt (Tab. 4 Anm. (*))","add_label":"+ Kultur","placement":"section","columns":[{"key":"label","label":"Kultur / Fläche","type":"text","required":true},{"key":"klasse_sub","label":"Tab.-7-Zeile (Güteklasse)","type":"lookup_key","required":true,"lookup":{"table_code":"TAB7_CLASS"}},{"key":"methode","label":"Bewässerungsmethode (Tab. 7)","type":"lookup_value","lookup":{"table_code":"TAB7_CLASS","key_column":"klasse_sub","value":"methode"}},{"key":"karenzzeit","label":"Karenzzeit (Tab. 7)","type":"lookup_value","lookup":{"table_code":"TAB7_CLASS","key_column":"klasse_sub","value":"karenzzeit_text"}},{"key":"laktierend","label":"Beweidung durch laktierendes Vieh","type":"boolean"},{"key":"klasse_rank","label":"Rang (1 = A strengste)","type":"derived","expr":"lookup(''TAB7_CLASS'', klasse_sub, ''rank'')","display":"badge","value_labels":{"1":"A","2":"B-1","3":"B-2","4":"C-1","5":"C-2","6":"D"}},{"key":"laktierend_konflikt","label":"laktierend","type":"derived","expr":"if(laktierend == true AND lookup(''TAB7_CLASS'', klasse_sub, ''laktierend_ausgeschlossen'') == true, 1, 0)","display":"badge","value_labels":{"0":"","1":"Güteklasse C: Beweidung durch laktierendes Vieh ausgeschlossen"}}],"footer":["gueteklasse_code"],"note":"(*) Wenn eine bewässerte Kulturpflanzenart in mehrere der oben genannten Kategorien fällt, gelten die Anforderungen der strengsten Kategorie."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
