INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'risiko_zeilen', 'Risikobewertung je Gefahr × Schutzgut (Arbeitshilfe C, Tab. 24/25)', 'json', NULL, false, '§6.3.5, Tab. 24, Tab. 25; §6.3.4, Tab. 23', 'Plan 3: Zeilen je Gefahr (Arbeitsblatt) × Schutzgut (TAB18) mit Schadensausmaß / Wahrscheinlichkeit (prod-Token) und Erwägungsgründen; Ausgangsrisiko je Zeile aus TAB23; ab "moderat" (Code ≥ 3, L2061) Vorsorgemaßnahmen + Restrisiko-Bewertung; max_rows → ausgangsrisiko_max_code (M12001-07-D2) / restrisiko_max_code (M12001-07-D1); löst die Skalare eintrittswahrscheinlichkeit / schadensausmass / risikoniveau_ausgangs / restrisiko_niveau ab (EQ-001 m1200_1-R-1, m1200_1-D-1); CR-014 auf restrisiko_max_code <= 2 STAGED (m1200_1-G-5).', 'imported_unverified', 'Dieser Systematik entsprechend wurde Arbeitshilfe C (Tabellen 24 und 25) aufgebaut. Sie muss für jede Gefahr gesondert bearbeitet werden, d. h. für mikrobiologische Pathogene, chemische Gefahren (nach Untergruppen) und für gefährliche Ereignisse und Störfälle. Zudem ist es erforderlich, den Schutzgütern eindeutige Bezeichnungen zuzuweisen und die Expositionswege zu beschreiben. Das Schutzgut Mensch kann zum Beispiel über verschiedene Expositionswege betroffen sein. — Nachdem pro Gefahr die relevanten Expositionswege sowie Exposition und Schaden erfasst wurden, erfolgt die Bewertung des Ausgangsrisikos. Hierzu werden das Schadensausmaß mit Erwägungsgrund sowie die Eintrittswahrscheinlichkeit mit Erwägungsgrund dargestellt und das Ausgangsrisiko bewertet (siehe Tabelle 23 und Tabelle 24). Ergibt sich hierbei ein sehr niedriges bzw. niedriges Risiko, so sind die ergriffenen Maßnahmen bereits ausreichend. Bei höherem Ausgangsrisiko ist die — Ergreifung von Vorsorgemaßnahmen erforderlich. Im zweiten Teil der Risikobewertung werden die risikomindernden Vorsorgemaßnahmen beschrieben und das sich daraus ergebende Schadensausmaß inklusive Erwägungsgrund und die Eintrittswahrscheinlich inklusive Erwägungsgrund eingetragen. Anschließend erfolgt nochmals die Risikobewertung zur Ermittlung des Restrisikos (siehe Tabelle 23 und Tabelle 24). — In Fällen, in denen im Rahmen der Risikobewertung ein moderates oder hohes Risikoniveau bestimmt wurde, sind durch das Risikomanagement entsprechende vorsorgende Maßnahmen zu etablieren, durch die alle identifizierten Risiken auf ein sehr niedriges oder niedriges Risikoniveau reduziert werden können. Ein Risikoniveau, das als sehr hoch eingestuft wird, ist nach bisherigen Erfahrungen mit Wasserwiederverwendungsanwendungen, die keine Trinkwasserqualität bereitstellen, eher ungewöhnlich (Asano et al. 2007; ISO 20426 2108; MoHR et al. 2020). Für Risiken, die als sehr niedrig oder niedrig eingestuft werden, sind in der Regel keine weitergehenden Anforderungen erforderlich, und das für den Menschen akzeptable Risikoniveau gilt als eingehalten.', 'register', '{"title":"Risikobewertung (Arbeitshilfe C)","subtitle":"Tab. 24/25 — je Gefahr × Schutzgut eine Zeile; Ausgangs- und Restrisiko nach Tab. 23","add_label":"+ Zeile","placement":"section","columns":[{"key":"gefahr","label":"Gefahr","type":"enum","required":true,"options":["mikrobiologisch","schwermetalle","pfas","organische_spurenstoffe","salze","mikroplastik"],"option_labels":{"mikrobiologisch":"mikrobielle Gefahren","schwermetalle":"Schwermetalle","pfas":"PFAS","organische_spurenstoffe":"organische Spurenstoffe","salze":"Salze","mikroplastik":"Mikroplastik"}},{"key":"schutzgut","label":"Schutzgut (Tab. 18)","type":"lookup_key","required":true,"lookup":{"table_code":"TAB18"}},{"key":"expositionsweg","label":"Expositionsweg","type":"lookup_value","lookup":{"table_code":"TAB18","key_column":"schutzgut","value":"expositionsweg"}},{"key":"exposition","label":"Bewertung der Exposition (Arbeitshilfe B)","type":"enum","required":true,"options":["hoch","mittel","gering","nicht_vorhanden"],"option_labels":{"hoch":"hoch","mittel":"mittel","gering":"gering","nicht_vorhanden":"nicht vorhanden"}},{"key":"schadensausmass","label":"Schadensausmaß (Tab. 22)","type":"enum","required":true,"options":["1","2","3","4","5"],"option_labels":{"1":"1 – Nicht signifikant","2":"2 – Niedrig","3":"3 – Moderat","4":"4 – Ernst","5":"5 – Katastrophal"}},{"key":"erwaegung_schaden","label":"Erwägungsgründe (Schaden)","type":"text"},{"key":"wahrscheinlichkeit","label":"Wahrscheinlichkeit (Tab. 21)","type":"enum","required":true,"options":["A","B","C","D","E"],"option_labels":{"A":"A – Selten","B":"B – Unwahrscheinlich","C":"C – Möglich","D":"D – Wahrscheinlich","E":"E – Sehr gewiss"}},{"key":"erwaegung_wahrsch","label":"Erwägungsgründe (Wahrscheinlichkeit)","type":"text"},{"key":"ausgangsrisiko","label":"Ausgangsrisiko (Tab. 23)","type":"derived","expr":"lookup(''TAB23'', wahrscheinlichkeit, schadensausmass, ''risikoniveau'')","value_labels":{"sehr_niedrig":"Sehr niedrig","niedrig":"Niedrig","moderat":"Moderat","hoch":"Hoch","sehr_hoch":"Sehr hoch"}},{"key":"ausgangsrisiko_code","label":"Ausgangsrisiko-Code","type":"derived","expr":"lookup(''TAB23'', wahrscheinlichkeit, schadensausmass, ''risikoniveau_code'')","display":"badge","value_labels":{"1":"Sehr niedrig","2":"Niedrig","3":"Moderat","4":"Hoch","5":"Sehr hoch"}},{"key":"massnahmen","label":"Vorsorgemaßnahmen","type":"text","required":true,"visible_when":"ausgangsrisiko_code >= 3"},{"key":"rest_schaden","label":"Restrisiko: Schadensmaß","type":"enum","required":true,"visible_when":"ausgangsrisiko_code >= 3","options":["1","2","3","4","5"],"option_labels":{"1":"1 – Nicht signifikant","2":"2 – Niedrig","3":"3 – Moderat","4":"4 – Ernst","5":"5 – Katastrophal"}},{"key":"rest_wahrsch","label":"Restrisiko: Wahrscheinlichkeit","type":"enum","required":true,"visible_when":"ausgangsrisiko_code >= 3","options":["A","B","C","D","E"],"option_labels":{"A":"A – Selten","B":"B – Unwahrscheinlich","C":"C – Möglich","D":"D – Wahrscheinlich","E":"E – Sehr gewiss"}},{"key":"restrisiko_code","label":"Restrisiko","type":"derived","expr":"if(ausgangsrisiko_code >= 3, lookup(''TAB23'', rest_wahrsch, rest_schaden, ''risikoniveau_code''), ausgangsrisiko_code)","display":"badge","value_labels":{"1":"Sehr niedrig","2":"Niedrig","3":"Moderat","4":"Hoch","5":"Sehr hoch"}}],"footer":["ausgangsrisiko_max_code","restrisiko_max_code"],"note":"In Fällen, in denen im Rahmen der Risikobewertung ein moderates oder hohes Risikoniveau bestimmt wurde, sind durch das Risikomanagement entsprechende vorsorgende Maßnahmen zu etablieren, durch die alle identifizierten Risiken auf ein sehr niedriges oder niedriges Risikoniveau reduziert werden können. Ein Risikoniveau, das als sehr hoch eingestuft wird, ist nach bisherigen Erfahrungen mit Wasserwiederverwendungsanwendungen, die keine Trinkwasserqualität bereitstellen, eher ungewöhnlich (Asano et al. 2007; ISO 20426 2108; MoHR et al. 2020). Für Risiken, die als sehr niedrig oder niedrig eingestuft werden, sind in der Regel keine weitergehenden Anforderungen erforderlich, und das für den Menschen akzeptable Risikoniveau gilt als eingehalten."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'risiko_zeilen') AND w.code = 'M12001-07' AND s.code = 'DWA-M-1200-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'ausgangsrisiko_max_code', 'Höchstes Ausgangsrisiko über die Zeilen als Code (1 = Sehr niedrig … 5 = Sehr hoch)', 'number', NULL, false, '§6.3.4, Tab. 23', 'Plan 3: Ausgabe der Gleichung M12001-07-D2 (max_rows über risiko_zeilen nach TAB23.risikoniveau_code).', 'imported_unverified', 'Risikoniveau $=$ Eintrittswahrscheinlichkeit × Schadensausmaß — In einem Fall, in dem ein Schaden wahrscheinlich eintritt und mit ernsten Konsequenzen verbunden ist, liegt ein hohes Risikoniveau vor. Dort, wo jedoch eine Gefahr eher unwahrscheinlich und zudem mit niedrigen Konsequenzen verbunden ist, liegt nur ein niedriges Risikoniveau vor (Tabelle 23).', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'ausgangsrisiko_max_code') AND w.code = 'M12001-07' AND s.code = 'DWA-M-1200-1';
