SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'restrisiko_max_code', 'Höchstes Restrisiko über die Zeilen als Code (1 = Sehr niedrig … 5 = Sehr hoch; Ziel ≤ 2)', 'number', NULL, false, '§6.3.4; §6.3.5', 'Plan 3: Ausgabe der Gleichung M12001-07-D1 (max_rows über risiko_zeilen nach restrisiko_code); "auf ein sehr niedriges oder niedriges Risikoniveau reduziert" (L2061) = Code ≤ 2; Übernahme in restrisiko_niveau / CR-014 STAGED (m1200_1-D-1 / -G-5).', 'imported_unverified', 'In Fällen, in denen im Rahmen der Risikobewertung ein moderates oder hohes Risikoniveau bestimmt wurde, sind durch das Risikomanagement entsprechende vorsorgende Maßnahmen zu etablieren, durch die alle identifizierten Risiken auf ein sehr niedriges oder niedriges Risikoniveau reduziert werden können. Ein Risikoniveau, das als sehr hoch eingestuft wird, ist nach bisherigen Erfahrungen mit Wasserwiederverwendungsanwendungen, die keine Trinkwasserqualität bereitstellen, eher ungewöhnlich (Asano et al. 2007; ISO 20426 2108; MoHR et al. 2020). Für Risiken, die als sehr niedrig oder niedrig eingestuft werden, sind in der Regel keine weitergehenden Anforderungen erforderlich, und das für den Menschen akzeptable Risikoniveau gilt als eingehalten.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'restrisiko_max_code') AND w.code = 'M12001-07' AND s.code = 'DWA-M-1200-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'stoerfaelle', 'Störfälle und gefährliche Ereignisse (Arbeitshilfe D, Tab. 26)', 'json', NULL, false, '§6.3.3, Tab. 20, Tab. 26', 'Plan 3: Zeilen je Ereignis (Teilelement, Teilprozess, Auslöser, Art der Gefährdung als Freitext — Tab. 26 druckt keine Liste, m1200_1-J-3; Schadensmaß / Wahrscheinlichkeit als prod-Token); Risiko je Zeile aus TAB23; max_rows → stoerfall_max_code (M12001-14-D1).', 'imported_unverified', '8 Neben den Gefahren durch mikrobiologische Pathogene und chemische Stoffe müssen auch betrieb9 liche Gefahren und gefährliche Ereignisse berücksichtigt werden. Diese gefährlichen Ereignisse, Stör10 oder Notfälle entstehen durch betriebliche Abweichungen vom Regelbetrieb oder unvorhergesehene 11 Vorkommnisse, wie zum Beispiel Fehlverhalten, Extremwettereignisse oder Vandalismus. Bei den un12 terschiedlichen Verfahrensschritten eines Wasserwiederverwendungssystems können exemplarisch 13 in ausgewählten Prozessen mögliche gefährliche Ereignisse oder Störfälle auftreten (Tabelle 21). Die 14 Erfassung der möglichen gefährlichen Ereignisse oder Störfälle erfolgt im Risikomanagementplan 15 mit der Arbeitshilfe D: Risikobewertung Störfälle und gefährliche Ereignisse, mit der das Ausgangs16 und Restrisiko ermittelt werden (siehe Tabelle 26). — \caption{Tabelle 26: Arbeitshilfe D: Darstellung von Schadensausmaß, Eintrittswahrscheinlichkeit und Ermittlung des Ausgangsrisikos für gefährliche Ereignisse und Störfälle} — \hline \multirow[t]{2}{*}{Teilelement des Systems} & \multirow[t]{2}{*}{Teilprozess} & \multirow[t]{2}{*}{Austöser / Ereignis} & \multirow[t]{2}{*}{Art der Gefährdung} & \multicolumn{5}{|c|}{Ausgangsrisiko} \\ — Die gleiche, systematische Darstellung der Risikobewertung wird auch für die Risiken durch gefährliche Ereignisse und Störfälle empfohlen (Tabelle 26).', 'register', '{"title":"Störfälle und gefährliche Ereignisse (Arbeitshilfe D)","subtitle":"Tab. 26 — je Teilelement / Teilprozess ein Ereignis mit Ausgangsrisiko nach Tab. 23","add_label":"+ Ereignis","placement":"section","columns":[{"key":"teilelement","label":"Teilelement des Systems","type":"text","required":true,"placeholder":"z. B. EZ-1, Abw-1, AWT-1, S-1, BW-1 (Tab. 26)"},{"key":"teilprozess","label":"Teilprozess","type":"text"},{"key":"ereignis","label":"Auslöser / Ereignis","type":"text","required":true},{"key":"gefaehrdung","label":"Art der Gefährdung","type":"text"},{"key":"schadensausmass","label":"Schadensmaß (Tab. 22)","type":"enum","required":true,"options":["1","2","3","4","5"],"option_labels":{"1":"1 – Nicht signifikant","2":"2 – Niedrig","3":"3 – Moderat","4":"4 – Ernst","5":"5 – Katastrophal"}},{"key":"erwaegung_schaden","label":"Erwägungsgründe (Schaden)","type":"text"},{"key":"wahrscheinlichkeit","label":"Wahrscheinlichkeit (Tab. 21)","type":"enum","required":true,"options":["A","B","C","D","E"],"option_labels":{"A":"A – Selten","B":"B – Unwahrscheinlich","C":"C – Möglich","D":"D – Wahrscheinlich","E":"E – Sehr gewiss"}},{"key":"erwaegung_wahrsch","label":"Erwägungsgründe (Wahrscheinlichkeit)","type":"text"},{"key":"risiko","label":"Risiko (Tab. 23)","type":"derived","expr":"lookup(''TAB23'', wahrscheinlichkeit, schadensausmass, ''risikoniveau'')","value_labels":{"sehr_niedrig":"Sehr niedrig","niedrig":"Niedrig","moderat":"Moderat","hoch":"Hoch","sehr_hoch":"Sehr hoch"}},{"key":"risiko_code","label":"Risiko-Code","type":"derived","expr":"lookup(''TAB23'', wahrscheinlichkeit, schadensausmass, ''risikoniveau_code'')","display":"badge","value_labels":{"1":"Sehr niedrig","2":"Niedrig","3":"Moderat","4":"Hoch","5":"Sehr hoch"}}],"footer":["stoerfall_max_code"],"note":"Die gleiche, systematische Darstellung der Risikobewertung wird auch für die Risiken durch gefährliche Ereignisse und Störfälle empfohlen (Tabelle 26)."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'stoerfaelle') AND w.code = 'M12001-14' AND s.code = 'DWA-M-1200-1';
