SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'flaechenverzeichnis', 'Flächenverzeichnis (Flächen, Kulturen, Güteklasse, Bewässerungsmenge und -methode)', 'json', NULL, false, '§7.3 (Art. 6 Abs. 3 EU-WasserWVVO); §7.4', 'Plan 3: Zeilen je zu bewässernder Fläche (CR-015 "Flächenverzeichnis, Kulturen, Güteklasse, Bewässerungsmenge und -methode"); count_rows → anwendungsbereich_count_calc (M12001-16-D1), Σ Menge → zusatzwasserbedarf_jahr_calc (M12001-16-D2); Ablösung von flaechenverzeichnis_vorhanden / anwendungsbereich_count / zusatzwasserbedarf_jahr STAGED (m1200_1-C-2 / -G-8).', 'imported_unverified', 'I Aussagen zu der Güteklasse des aufbereiteten Wassers und dem Verwendungszweck bzw. den Verwendungszwecken (Kulturen, Nutzungen etc.), für den bzw. die das aufbereitete Wasser gemäß Anhang I zu genehmigen ist, den potenziellen Verbrauchsstellen linkl. eines Flächenverzeichnisses der zu bewässernden Flächen), den Aufbereitungseinrichtungen und der geschätzten jährlichen Menge des aufzubereitenden Wassers, dem Zustand sowie der Nutzung der Flächen einschließlich der Bewässerungsmethode; — Neben den im RMP festgelegten Anforderungen an den Endnutzer muss die Aufbringungserlaubnis konkrete Angaben zum Endnutzer bzw. dessen Betrieb sowie zu den zu bewässernden Kulturen oder urbanen Flächen inkl. der Güteklasse des aufbereiteten Wassers und des Verwendungszwecks beinhalten. Dazu gehören auch die Auflagen zum Monitoring und Berichtspflichten. Gegebenenfalls sind weitere gesetzliche und andere Anforderungen, zum Beispiel Nachweis der bedarfsgerechten Bewässerung, in dieser Erlaubnis zu berücksichtigen.', 'register', '{"title":"Flächenverzeichnis der zu bewässernden Flächen","subtitle":"Art. 6 Abs. 3 EU-WasserWVVO / §7.4 — je Fläche Kultur, Güteklasse (Tab.-7-Zeile), Bewässerungsmethode und -menge","add_label":"+ Fläche","placement":"section","columns":[{"key":"flaeche","label":"Fläche (Bezeichnung / Flurstück)","type":"text","required":true},{"key":"flaeche_ha","label":"Größe","type":"number","unit":"ha","min":0,"aria_label":"Flächengröße in Hektar"},{"key":"kultur","label":"Kultur / Nutzung","type":"text","required":true},{"key":"klasse_sub","label":"Güteklasse (Tab.-7-Zeile)","type":"lookup_key","required":true,"lookup":{"table_code":"TAB7_CLASS"}},{"key":"methode_zulaessig","label":"Zulässige Methode (Tab. 7)","type":"lookup_value","lookup":{"table_code":"TAB7_CLASS","key_column":"klasse_sub","value":"methode"}},{"key":"methode","label":"Geplante Bewässerungsmethode","type":"text","required":true},{"key":"menge_m3","label":"Bewässerungsmenge (Jahr)","type":"number","unit":"m³/a","required":true,"min":0,"aria_label":"jährliche Bewässerungsmenge"},{"key":"karenzzeit","label":"Karenzzeit (Tab. 7)","type":"lookup_value","lookup":{"table_code":"TAB7_CLASS","key_column":"klasse_sub","value":"karenzzeit_text"}}],"footer":["anwendungsbereich_count_calc","zusatzwasserbedarf_jahr_calc"],"note":"Neben den im RMP festgelegten Anforderungen an den Endnutzer muss die Aufbringungserlaubnis konkrete Angaben zum Endnutzer bzw. dessen Betrieb sowie zu den zu bewässernden Kulturen oder urbanen Flächen inkl. der Güteklasse des aufbereiteten Wassers und des Verwendungszwecks beinhalten. Dazu gehören auch die Auflagen zum Monitoring und Berichtspflichten. Gegebenenfalls sind weitere gesetzliche und andere Anforderungen, zum Beispiel Nachweis der bedarfsgerechten Bewässerung, in dieser Erlaubnis zu berücksichtigen."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'flaechenverzeichnis') AND w.code = 'M12001-16' AND s.code = 'DWA-M-1200-1';
