SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'validierung_min_share_pct', 'Mindestanteil der Validierungsproben, die die Leistungsziele erreichen — Tab. 8 (A 90 % · B-1 / C-1 50 %)', 'number', '%', false, '§5.2, Tab. 8', 'Plan 3: Wert aus TAB8 zur zugeordneten Wassergüteklasse (locked — Mindestanforderung); die Routineproben-Zeilen vergleichen dagegen (M12001-09-D1); Vergleichswert für validierungs_compliance_pct (M12001-12, m1200_1-C-3); CR-006 STAGED (m1200_1-G-4).', 'imported_unverified', 'b）Gemäß LAWA（2022）sollten die Leistungsziele neben Güteklasse A auch für die Güteklassen B－1 und C－1 gelten． Klasse A：Mindestens 90 \％der Proben müssen die Leistungsziele erreichen．Klassen B－1／C－1：Mindestens 50 \％ der Proben müssen die Leistungsziele erreichen． \\ — Die Leistungsziele ( $\log _{10}$-Reduktion) für die Überwachung zur Validierung der Reduktion von ausgewählten Indikator-Mikroorganismen sind in Tabelle 8 festgelegt und müssen unter Berücksichtigung der Konzentrationen im Rohabwasser, das in die kommunale Kläranlage eingeleitet wird, an der Stelle der Einhaltung erfüllt werden. Für die Wassergüteklasse A müssen mindestens $90 \%$, für die Wassergüteklassen B-1 und C-1 mindestens $50 \%$ der Validierungsproben die Leistungsziele erreichen oder übersteigen (Näheres siehe Merkblatt DWA-M 1200-2).', 'lookup_fill', '{"source_label":"Tab. 8 (Arbeitshilfe A)"}'::jsonb, '{"table_code":"TAB8","role":"limit","keys":[{"column":"klasse","from_symbol":"gueteklasse_zugeordnet"}],"value":"validierung_pass_share_pct"}'::jsonb, 'gueteklasse_zugeordnet IN {''A'', ''B-1'', ''C-1''}', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'validierung_min_share_pct') AND w.code = 'M12001-09' AND s.code = 'DWA-M-1200-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'routine_min_share_pct', 'Mindestanteil der Routineproben, die die Werte einhalten — Tab. 8 (90 % für jede Klasse)', 'number', '%', false, '§5.2, Tab. 8', 'Plan 3: Wert aus TAB8 zur zugeordneten Wassergüteklasse (locked — Mindestanforderung); die Routineproben-Zeilen vergleichen dagegen (M12001-09-D1); CR-008 auf compliance_quote_calc >= routine_min_share_pct STAGED (m1200_1-G-7).', 'imported_unverified', 'In Anlehnung an die EU-WasserWVVO müssen die vorgegebenen Werte für E. coli, Legionella spp. und intestinale Nematoden in Tabelle 8 in mindestens $90 \%$ der Proben eingehalten werden. Keiner der Werte der Proben darf die maximale Abweichungsgrenze von einer $\log _{10}$-Stufe für den vorgegebenen Wert für E. coli und Legionella spp. und $100 \%$ des vorgegebenen Werts für intestinale Nematoden überschreiten. — Die vorgegebenen Werte für $\mathrm{BSB}_{5}$, AFS und Trübung bei Güteklasse A bis C müssen in mindestens $90 \%$ der Proben eingehalten werden. Keiner der Werte der Proben darf die maximale Abweichungsgrenze von $100 \%$ des vorgegebenen Werts überschreiten.', 'lookup_fill', '{"source_label":"Tab. 8 (Arbeitshilfe A)"}'::jsonb, '{"table_code":"TAB8","role":"limit","keys":[{"column":"klasse","from_symbol":"gueteklasse_zugeordnet"}],"value":"routine_pass_share_pct"}'::jsonb, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'routine_min_share_pct') AND w.code = 'M12001-09' AND s.code = 'DWA-M-1200-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'truebung_avg_limit', 'Trübung — Durchschnittswert innerhalb 24 h — Tab. 8 Anm. f) (Polstoff/Mikrosieb/Raumfilter 2 NTU · Membran –)', 'number', 'NTU', false, '§5.2, Tab. 8 Anm. f)', 'Plan 3: Wert aus TAB8_NOTE_F zum gewählten Filtrationsverfahren (filtration_typ von M12001-10; anhaltswert — "sollten … nicht überschreiten"); Token-Zuordnung membran + vier Membranverfahren m1200_1-E-2; truebung_max_value bleibt manuell (m1200_1-C-3).', 'imported_unverified', 'f）Gemäß DWA（2023b）．Bei Polstofffiltern，Mikrosieben und Raumfiltern sollten die Trübungswerte im filtrierten Wasser keinen der folgenden Werte überschreiten：Ein Durchschnittswert von 2 NTU innerhalb eines Zeitraums von $24 \mathrm{~h}, 5 \mathrm{NTU}$ in mehr als $5 \%$ der Zeit innerhalb eines Zeitraums von 24 h und 10 NTU zu keiner Zeit． \\ — Wird die Filtration durch Membranverfahren gewährleistet（Mikrofiltration，Ultrafiltration，Nanofiltration， Umkehrosmose），sollten die Trübungswerte im filtrierten Wasser keinen der folgenden Werte überschreiten： $0,2 \mathrm{NTU}$ in mehr als $5 \%$ der Zeit innerhalb eines Zeitraums von 24 h und 0，5 NTU zu keiner Zeit． \\', 'lookup_fill', '{"source_label":"Tab. 8 Anm. f)"}'::jsonb, '{"table_code":"TAB8_NOTE_F","role":"limit","keys":[{"column":"filtration_typ","from_symbol":"filtration_typ"}],"value":"ntu_avg_24h"}'::jsonb, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'truebung_avg_limit') AND w.code = 'M12001-09' AND s.code = 'DWA-M-1200-1';
