SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'truebung_5pct_limit', 'Trübung — in mehr als 5 % der Zeit (24 h) nicht zu überschreiten — Tab. 8 Anm. f) (Polstoff/Mikrosieb/Raumfilter 5 NTU · Membran 0,2 NTU)', 'number', 'NTU', false, '§5.2, Tab. 8 Anm. f)', 'Plan 3: Wert aus TAB8_NOTE_F zum gewählten Filtrationsverfahren (filtration_typ von M12001-10; anhaltswert — "sollten … nicht überschreiten"); Token-Zuordnung membran + vier Membranverfahren m1200_1-E-2; truebung_max_value bleibt manuell (m1200_1-C-3).', 'imported_unverified', 'f）Gemäß DWA（2023b）．Bei Polstofffiltern，Mikrosieben und Raumfiltern sollten die Trübungswerte im filtrierten Wasser keinen der folgenden Werte überschreiten：Ein Durchschnittswert von 2 NTU innerhalb eines Zeitraums von $24 \mathrm{~h}, 5 \mathrm{NTU}$ in mehr als $5 \%$ der Zeit innerhalb eines Zeitraums von 24 h und 10 NTU zu keiner Zeit． \\ — Wird die Filtration durch Membranverfahren gewährleistet（Mikrofiltration，Ultrafiltration，Nanofiltration， Umkehrosmose），sollten die Trübungswerte im filtrierten Wasser keinen der folgenden Werte überschreiten： $0,2 \mathrm{NTU}$ in mehr als $5 \%$ der Zeit innerhalb eines Zeitraums von 24 h und 0，5 NTU zu keiner Zeit． \\', 'lookup_fill', '{"source_label":"Tab. 8 Anm. f)"}'::jsonb, '{"table_code":"TAB8_NOTE_F","role":"limit","keys":[{"column":"filtration_typ","from_symbol":"filtration_typ"}],"value":"ntu_5pct"}'::jsonb, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'truebung_5pct_limit') AND w.code = 'M12001-09' AND s.code = 'DWA-M-1200-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'truebung_never_limit', 'Trübung — zu keiner Zeit zu überschreiten — Tab. 8 Anm. f) (Polstoff/Mikrosieb/Raumfilter 10 NTU · Membran 0,5 NTU)', 'number', 'NTU', false, '§5.2, Tab. 8 Anm. f)', 'Plan 3: Wert aus TAB8_NOTE_F zum gewählten Filtrationsverfahren (filtration_typ von M12001-10; anhaltswert — "sollten … nicht überschreiten"); Token-Zuordnung membran + vier Membranverfahren m1200_1-E-2; truebung_max_value bleibt manuell (m1200_1-C-3).', 'imported_unverified', 'f）Gemäß DWA（2023b）．Bei Polstofffiltern，Mikrosieben und Raumfiltern sollten die Trübungswerte im filtrierten Wasser keinen der folgenden Werte überschreiten：Ein Durchschnittswert von 2 NTU innerhalb eines Zeitraums von $24 \mathrm{~h}, 5 \mathrm{NTU}$ in mehr als $5 \%$ der Zeit innerhalb eines Zeitraums von 24 h und 10 NTU zu keiner Zeit． \\ — Wird die Filtration durch Membranverfahren gewährleistet（Mikrofiltration，Ultrafiltration，Nanofiltration， Umkehrosmose），sollten die Trübungswerte im filtrierten Wasser keinen der folgenden Werte überschreiten： $0,2 \mathrm{NTU}$ in mehr als $5 \%$ der Zeit innerhalb eines Zeitraums von 24 h und 0，5 NTU zu keiner Zeit． \\', 'lookup_fill', '{"source_label":"Tab. 8 Anm. f)"}'::jsonb, '{"table_code":"TAB8_NOTE_F","role":"limit","keys":[{"column":"filtration_typ","from_symbol":"filtration_typ"}],"value":"ntu_never"}'::jsonb, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'truebung_never_limit') AND w.code = 'M12001-09' AND s.code = 'DWA-M-1200-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'toc_korrelation_nachgewiesen', 'TOC-Messung mit nachgewiesener BSB5/TOC-Korrelation (Tab. 8 Anm. d) — BSB5-Bestimmung entfällt', 'boolean', NULL, false, '§5.2, Tab. 8 Anm. d)', 'Plan 3: dokumentierte Substitution nach Anm. d) (m1200_1-P-1); die Ausblendung / Optionalität von bsb5_value dazu ist STAGED (m1200_1-G-2, konsumiertes Feld).', 'imported_unverified', 'd）Auf die Bestimmung des $\mathrm{BSB}_{5}$ kann bei Anwendung einer TOC－Messung verzichtet werden，wenn die Korrelation zwischen $\mathrm{BSB}_{5}$ und TOC nachgewiesen wird． \\', 'attestation', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'toc_korrelation_nachgewiesen') AND w.code = 'M12001-09' AND s.code = 'DWA-M-1200-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'truebung_kontinuierlich_ueberwacht', 'Trübung kontinuierlich überwacht und eingehalten (Tab. 8 Anm. e) — AFS-Messung nicht zusätzlich erforderlich', 'boolean', NULL, false, '§5.2, Tab. 8 Anm. e)', 'Plan 3: dokumentierte Substitution nach Anm. e) (m1200_1-P-1); die Optionalität von afs_value dazu ist STAGED (m1200_1-G-2, konsumiertes Feld).', 'imported_unverified', 'e）Wenn die Anforderungen an die Trübung kontinuierlich überwacht und eingehalten werden，kann davon ausgegan－ gen werden，dass auch die Anforderungen an die AFS eingehalten werden und die Messung der AFS somit nicht zusätzlich erforderlich ist．AFS kann mit der Trübung anlagenspezifisch korreliert werden：AFS lin mg／ll／Trübung （in NTU）＝1，3 bis 2，4（Tchobanoglous et al．2014）． \\', 'attestation', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'truebung_kontinuierlich_ueberwacht') AND w.code = 'M12001-09' AND s.code = 'DWA-M-1200-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'routineproben', 'Routineproben (Datum, Parameter, Messwert → Einhaltung des Tab.-8-Werts)', 'json', NULL, false, '§5.2; §6.6.2', 'Plan 3: Zeilen je Routineprobe; Grenzwert je Zeile aus den Tab.-8-Feldern dieses Arbeitsblatts (e_coli_limit … nematoden_limit, Zeilen-Scope); Anteil eingehaltener Proben → compliance_quote_calc (M12001-09-D1); ersetzt das manuell getippte compliance_quote_pct (M12001-12) — STAGED (m1200_1-C-2 / -G-7); die log10-Abweichungsgrenze (L1143) ist nicht kodiert (Residuum).', 'imported_unverified', 'In Anlehnung an die EU-WasserWVVO müssen die vorgegebenen Werte für E. coli, Legionella spp. und intestinale Nematoden in Tabelle 8 in mindestens $90 \%$ der Proben eingehalten werden. Keiner der Werte der Proben darf die maximale Abweichungsgrenze von einer $\log _{10}$-Stufe für den vorgegebenen Wert für E. coli und Legionella spp. und $100 \%$ des vorgegebenen Werts für intestinale Nematoden überschreiten. — Die vorgegebenen Werte für $\mathrm{BSB}_{5}$, AFS und Trübung bei Güteklasse A bis C müssen in mindestens $90 \%$ der Proben eingehalten werden. Keiner der Werte der Proben darf die maximale Abweichungsgrenze von $100 \%$ des vorgegebenen Werts überschreiten. — Die Betreiber der Aufbereitungseinrichtungen führen eine Routineüberwachung durch, um zu überprüfen, ob das aufbereitete Wasser den Anforderungen an die Wasserqualität gemäß Genehmigung entspricht (siehe Anhang I Abschnitt 2b EU-WasserWVVO, Mindestanforderungen an die Überwachung). Die Proben, die verwendet werden, um die Einhaltung der mikrobiologischen Parameter an der Stelle der Einhaltung zu überprüfen, sind gemäß der Norm DIN EN ISO 19458:2006 oder anderen nationalen oder internationalen Normen, die eine gleichwertige Qualität gewährleisten, zu entnehmen. In Tabelle 27 sind die Anforderungen an die Häufigkeit der Beprobung aufgeführt.', 'register', '{"title":"Routineproben (Stelle der Einhaltung)","subtitle":"§5.2 / §6.6.2 — je Probe Datum, Parameter und Messwert; Vergleich mit dem Tab.-8-Grenzwert der Klasse (Legionella strikt \"<\", sonst \"≤\"); Proben ohne Grenzwert zählen nicht","add_label":"+ Probe","placement":"section","columns":[{"key":"date","label":"Datum","type":"date","required":true},{"key":"parameter","label":"Parameter","type":"enum","required":true,"options":["e_coli","enterokokken","bsb5","afs","truebung","legionella","nematoden"],"option_labels":{"e_coli":"E. coli (KBE/100 ml)","enterokokken":"Intestinale Enterokokken (KBE/100 ml)","bsb5":"BSB5 (mg/l)","afs":"AFS (mg/l)","truebung":"Trübung (NTU)","legionella":"Legionella spp. (KBE/l)","nematoden":"Intestinale Nematoden (Eier/l)"},"discriminator":true},{"key":"wert","label":"Messwert","type":"number","required":true,"min":0,"aria_label":"Messwert der Probe"},{"key":"limit","label":"Grenzwert (Tab. 8)","type":"derived","expr":"if(parameter == ''e_coli'', e_coli_limit, if(parameter == ''enterokokken'', enterokokken_limit, if(parameter == ''bsb5'', bsb5_limit, if(parameter == ''afs'', afs_limit, if(parameter == ''truebung'', truebung_limit, if(parameter == ''legionella'', legionella_limit, nematoden_limit))))))"},{"key":"relevant","label":"Grenzwert vorhanden","type":"derived","expr":"if(limit IS NULL, 0, 1)","display":"badge","value_labels":{"0":"kein Grenzwert für diese Klasse","1":""}},{"key":"ok","label":"eingehalten","type":"derived","expr":"if(limit IS NULL, 0, if(parameter == ''legionella'', if(wert < limit, 1, 0), if(wert <= limit, 1, 0)))","display":"badge","value_labels":{"0":"überschritten","1":"eingehalten"}}],"footer":["compliance_quote_calc"],"note":"In Anlehnung an die EU-WasserWVVO müssen die vorgegebenen Werte für E. coli, Legionella spp. und intestinale Nematoden in Tabelle 8 in mindestens $90 \\%$ der Proben eingehalten werden. Keiner der Werte der Proben darf die maximale Abweichungsgrenze von einer $\\log _{10}$-Stufe für den vorgegebenen Wert für E. coli und Legionella spp. und $100 \\%$ des vorgegebenen Werts für intestinale Nematoden überschreiten."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'routineproben') AND w.code = 'M12001-09' AND s.code = 'DWA-M-1200-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'compliance_quote_calc', 'Anteil der Routineproben, die den Tab.-8-Wert einhalten', 'number', '%', false, '§5.2', 'Plan 3: Ausgabe der Gleichung M12001-09-D1 (count_rows(ok == 1) · 100 / count_rows(relevant == 1) über routineproben; 100 = Prozent); Sollwert routine_min_share_pct (90 %); Übernahme als compliance_quote_pct (M12001-12) / CR-008 STAGED (m1200_1-C-2 / -G-7).', 'imported_unverified', 'In Anlehnung an die EU-WasserWVVO müssen die vorgegebenen Werte für E. coli, Legionella spp. und intestinale Nematoden in Tabelle 8 in mindestens $90 \%$ der Proben eingehalten werden. Keiner der Werte der Proben darf die maximale Abweichungsgrenze von einer $\log _{10}$-Stufe für den vorgegebenen Wert für E. coli und Legionella spp. und $100 \%$ des vorgegebenen Werts für intestinale Nematoden überschreiten. — Die vorgegebenen Werte für $\mathrm{BSB}_{5}$, AFS und Trübung bei Güteklasse A bis C müssen in mindestens $90 \%$ der Proben eingehalten werden. Keiner der Werte der Proben darf die maximale Abweichungsgrenze von $100 \%$ des vorgegebenen Werts überschreiten.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'compliance_quote_calc') AND w.code = 'M12001-09' AND s.code = 'DWA-M-1200-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'pfas20_limit_ng_l', 'Summe PFAS-20 — Beurteilungswert (Tab. 19 Kategorie 3: < 100 ng/l = 0,10 µg/l)', 'number', 'ng/l', false, '§6.3.3, Tab. 19; §5.2', 'Plan 3: Ausgabe der Gleichung M12001-09-D2 (lookup TAB19 Kategorie 3, grenzwert_ng_l); CR-013 (pfas20_value < 100) vergleicht gegen die gedruckte 100 — Umstellung auf dieses Symbol STAGED (m1200_1-G-6).', 'imported_unverified', '\hline Kategorie 1: einfach entfernbar & Kategorie 2: moderat entfernbar & Kategorie 3: Vorsorgescreening \\
\hline Amisulprid & Benzotriazol & Summe PFAS-20<100 ng/l \\
\hline Carbamazepin & 4- und 5-Methylbenzotriazol & \\
\hline Citalopram & Gabapentin ${ }^{(*)}$ & \\
\hline Clarithromycin & Candesartan & \\
\hline Diclofenac & Irbesartan & \\
\hline Hydrochlorothiazid & & \\
\hline Metoprolol & & \\
\hline Venlafaxin & & \\
\hline Valsartansäure & & \\ — Dort wo gemäß der Risikobewertung keine zusätzliche Aufbereitung (gezielte Spurenstoffelimination) nötig ist (Szenario II), ist keine regelmäßige Messung von organischen Spurenstoffen erforderlich. Sie ist jedoch in Abhängigkeit von den Ergebnissen des Screenings der Leitsubstanzen empfehlenswert, um mögliche Veränderungen frühzeitig zu erkennen (siehe oben). In allen Fällen muss regelmäßig nachgewiesen werden, dass der Beurteilungswert für die Summe der PFAS-20 von $0,10 \mu \mathrm{~g} / \mathrm{l}$ sicher eingehalten werden kann.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
