INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'messstellen', 'Umweltmonitoring-Programm (Parameter, Matrix, Partei, Intervall, Ort)', 'json', NULL, false, '§6.6.3 (KRM 9); §6.6.1', 'Plan 3: Zeilen je zu untersuchendem Parameter mit den fünf Pflichtangaben aus §6.6.3 (L2395–L2399) plus Vorbelastung / Messwert; der BBodSchV-Vorsorgewert ist externes Recht (Content-Boundary: nur Verweis, eigene Eingabe); die Skalare cd_value … zn_value bleiben (Residuum).', 'imported_unverified', 'Das Umweltmonitoring ist Teil des RMP und umfasst verschiedene Umweltkompartimente und Parameter. Im Risikomanagementplan ist ein Überwachungsprogramm nach den allgemein anerkannten Regeln der Technik festzulegen, das Folgendes enthält:

I zu untersuchende Parameter;
I zu untersuchende Matrix;
I für die Untersuchung zuständige Partei;
I Untersuchungsintervalle für die jeweiligen Parameter;
I Ort oder Orte der Probennahme. — I Überwachung der bewässerten Pflanzen;
I Überwachung des Bodens, zum Beispiel im Hinblick auf den Salzgehalt;
- Überwachung von Quellschüttungen in benachbarten Gebieten;

I Überwachung des Grundwassers, zum Beispiel bei oberflächennahen Grundwasserleitern, oder von angrenzenden Oberflächengewässern zum Beispiel bei Hanglage oder Dränagen;

I Verhinderung der Verstopfung von Bewässerungssystemen, zum Beispiel Tropf- und Sprinklerbewässerung.', 'register', '{"title":"Umweltmonitoring-Programm (§6.6.3)","subtitle":"je Parameter: Matrix, zuständige Partei, Untersuchungsintervall, Ort(e) der Probennahme; Vorbelastung und Messwert; Vorsorgewert nach BBodSchV nur als Verweis (externes Recht)","add_label":"+ Parameter","placement":"section","columns":[{"key":"parameter","label":"Parameter","type":"text","required":true},{"key":"matrix","label":"Matrix","type":"enum","required":true,"options":["pflanzen","boden","quellschuettung","grundwasser","oberflaechengewaesser"],"option_labels":{"pflanzen":"bewässerte Pflanzen","boden":"Boden","quellschuettung":"Quellschüttung (benachbarte Gebiete)","grundwasser":"Grundwasser","oberflaechengewaesser":"angrenzende Oberflächengewässer"}},{"key":"partei","label":"Zuständige Partei","type":"text","required":true},{"key":"intervall","label":"Untersuchungsintervall","type":"text","required":true},{"key":"ort","label":"Ort(e) der Probennahme","type":"text","required":true},{"key":"vorbelastung","label":"Vorbelastung","type":"number","aria_label":"Vorbelastung vor Inbetriebnahme"},{"key":"messwert","label":"Messwert","type":"number","aria_label":"aktueller Messwert"},{"key":"bbodschv_wert","label":"Vorsorgewert BBodSchV (Verweis, eigene Eingabe)","type":"number","aria_label":"Vorsorgewert nach BBodSchV"},{"key":"einheit","label":"Einheit","type":"text"}],"note":"Im Risikomanagementplan ist ein Überwachungsprogramm nach den allgemein anerkannten Regeln der Technik festzulegen, das Folgendes enthält:\n\nI zu untersuchende Parameter;\nI zu untersuchende Matrix;\nI für die Untersuchung zuständige Partei;\nI Untersuchungsintervalle für die jeweiligen Parameter;\nI Ort oder Orte der Probennahme."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'messstellen') AND w.code = 'M12001-13' AND s.code = 'DWA-M-1200-1';
COMMIT;
